'use strict';

// MODULES //

import numelDimension from '@stdlib/ndarray-base-numel-dimension';
import getStride from '@stdlib/ndarray-base-stride';
import getOffset from '@stdlib/ndarray-base-offset';
import getData from '@stdlib/ndarray-base-data-buffer';
import { ndarray as strided } from '@stdlib/blas-ext-base-dfirst-index-less-than';
import ndarraylike2scalar from '@stdlib/ndarray-base-ndarraylike2scalar';


// MAIN //

/**
* Returns the index of the first element in a one-dimensional double-precision floating-point ndarray which is less than a corresponding element in another one-dimensional double-precision floating-point ndarray.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   first one-dimensional input ndarray.
*     -   second one-dimensional input ndarray.
*     -   a zero-dimensional ndarray containing the index from which to begin searching.
*
* -   When comparing elements, the function checks whether an element in the first one-dimensional input ndarray is less than a corresponding element in the second one-dimensional input ndarray using the less-than operator `<`. As a consequence, comparisons involving `NaN` always evaluate to `false`.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {integer} index
*
* @example
* import Float64Vector from '@stdlib/ndarray-vector-float64';
* import scalar2ndarray from '@stdlib/ndarray-from-scalar';
*
* var x = new Float64Vector( [ 0.0, 0.0, 0.0, 0.0 ] );
* var y = new Float64Vector( [ 0.0, 0.0, 1.0, 0.0 ] );
*
* var fromIndex = scalar2ndarray( 0, {
*     'dtype': 'generic'
* });
*
* var idx = dfirstIndexLessThan( [ x, y, fromIndex ] );
* // returns 2
*/
function dfirstIndexLessThan( arrays ) {
	var fromIndex;
	var idx;
	var ox;
	var oy;
	var sx;
	var sy;
	var N;
	var x;
	var y;

	x = arrays[ 0 ];
	y = arrays[ 1 ];
	N = numelDimension( x, 0 );
	fromIndex = ndarraylike2scalar( arrays[ 2 ] );

	if ( fromIndex < 0 ) {
		fromIndex += N;
		if ( fromIndex < 0 ) {
			fromIndex = 0;
		}
	} else if ( fromIndex >= N ) {
		return -1;
	}
	N -= fromIndex;
	sx = getStride( x, 0 );
	sy = getStride( y, 0 );
	ox = getOffset( x ) + ( sx*fromIndex );
	oy = getOffset( y ) + ( sy*fromIndex );

	idx = strided( N, getData( x ), sx, ox, getData( y ), sy, oy );
	if ( idx >= 0 ) {
		idx += fromIndex;
	}
	return idx;
}


// EXPORTS //

export default dfirstIndexLessThan;
